import { useEffect, useState } from "react";
import vscode from "../vscode";

interface ShortcutEntry {
  key: string;
  title: string;
  command: string;
}

/**
 * Keyboard shortcut cheat sheet. The list is generated by the extension from
 * its package.json keybindings + command titles, so it never drifts.
 */
export default function ShortcutRef() {
  const [shortcuts, setShortcuts] = useState<ShortcutEntry[] | null>(null);

  useEffect(() => {
    const handler = (event: MessageEvent) => {
      const msg = event.data;
      if (msg?.type === "shortcutsData" && Array.isArray(msg.shortcuts)) {
        setShortcuts(msg.shortcuts as ShortcutEntry[]);
      }
    };
    window.addEventListener("message", handler);
    vscode.postMessage({ type: "getShortcuts" });
    return () => window.removeEventListener("message", handler);
  }, []);

  return (
    <div className="shortcut-panel">
      <div className="shortcut-panel-header">
        All shortcuts use <kbd className="shortcut-key">Alt+D</kbd> as a chord prefix — press Alt+D, release, then press the key.
      </div>
      {shortcuts === null ? (
        <div className="loading-state" role="status">
          <span className="spinner" aria-hidden="true" /> Loading shortcuts...
        </div>
      ) : shortcuts.length === 0 ? (
        <div className="section-empty">No keybindings found</div>
      ) : (
        <div className="shortcut-grid">
          {shortcuts.map((s) => (
            <div key={`${s.command}-${s.key}`} className="shortcut-row" title={s.command}>
              <kbd className="shortcut-key">{s.key}</kbd>
              <span className="shortcut-desc">{s.title}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
